{% comment %} QuizSnap Quiz Embed Block — Online Store 2.0 App Block {% endcomment %}

{% if block.settings.quiz_slug != blank %}
  {%- assign qs_primary_color = block.settings.button_color | default: '#5C6AC4' -%}
  {%- assign qs_width_class = 'quizsnap-width--' | append: block.settings.width | default: 'full' -%}
  {%- assign qs_display_mode = block.settings.display_mode | default: 'embedded' -%}

  <div
    class="quizsnap-block {{ qs_width_class }}"
    data-block-id="{{ block.id }}"
    {{ block.shopify_attributes }}
  >
    {%- if qs_display_mode == 'embedded' -%}
      <div
        id="quizsnap-{{ block.id }}"
        class="quizsnap"
        data-quizsnap-quiz="{{ block.settings.quiz_slug }}"
        data-shop="{{ shop.permanent_domain }}"
        data-display-mode="embedded"
        data-primary-color="{{ qs_primary_color }}"
        style="--qs-primary: {{ qs_primary_color }};"
        role="region"
        aria-label="{{ block.settings.quiz_slug | replace: '-', ' ' | capitalize }} quiz"
      >
        <div class="quizsnap-loading" role="status" aria-live="polite">
          <div class="quizsnap-spinner" aria-hidden="true"></div>
          <span class="quizsnap-loading__text">Loading quiz&hellip;</span>
        </div>
      </div>

    {%- elsif qs_display_mode == 'popup' or qs_display_mode == 'slide-in' -%}
      <div
        id="quizsnap-trigger-{{ block.id }}"
        class="quizsnap-trigger-wrap"
        data-quizsnap-quiz="{{ block.settings.quiz_slug }}"
        data-shop="{{ shop.permanent_domain }}"
        data-display-mode="{{ qs_display_mode }}"
        data-primary-color="{{ qs_primary_color }}"
        style="--qs-primary: {{ qs_primary_color }};"
      >
        <button
          class="quizsnap-trigger-btn"
          type="button"
          aria-haspopup="dialog"
          aria-controls="quizsnap-modal-{{ block.id }}"
          style="background-color: {{ qs_primary_color }};"
        >
          {{ block.settings.button_text | default: 'Take the quiz' }}
        </button>
      </div>

      <div
        id="quizsnap-modal-{{ block.id }}"
        class="quizsnap-overlay quizsnap-overlay--{{ qs_display_mode }}"
        role="dialog"
        aria-modal="true"
        aria-label="{{ block.settings.quiz_slug | replace: '-', ' ' | capitalize }} quiz"
        aria-hidden="true"
        hidden
      >
        <div class="quizsnap-overlay__backdrop" data-quizsnap-close aria-hidden="true"></div>
        <div class="quizsnap-overlay__panel">
          <button
            class="quizsnap-overlay__close"
            type="button"
            aria-label="Close quiz"
            data-quizsnap-close
          >
            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
              <path d="M15 5L5 15M5 5l10 10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
            </svg>
          </button>
          <div
            class="quizsnap"
            data-quizsnap-quiz="{{ block.settings.quiz_slug }}"
            data-shop="{{ shop.permanent_domain }}"
            data-display-mode="{{ qs_display_mode }}"
            data-primary-color="{{ qs_primary_color }}"
            data-modal-id="quizsnap-modal-{{ block.id }}"
            style="--qs-primary: {{ qs_primary_color }};"
          >
            <div class="quizsnap-loading" role="status" aria-live="polite">
              <div class="quizsnap-spinner" aria-hidden="true"></div>
              <span class="quizsnap-loading__text">Loading quiz&hellip;</span>
            </div>
          </div>
        </div>
      </div>
    {%- endif -%}
  </div>

  {% comment %} Lazy-load the widget assets {% endcomment %}
  {{ 'quiz-widget.css' | asset_url | stylesheet_tag }}

  <script>
    (function () {
      var APP_URL = {{ app.url | json }};
      var blockId = {{ block.id | json }};

      function loadWidget() {
        if (document.querySelector('script[data-quizsnap-loaded]')) return;
        var script = document.createElement('script');
        script.src = APP_URL + '/assets/quiz-widget.js';
        script.defer = true;
        script.dataset.quizsnapLoaded = '1';
        script.dataset.appUrl = APP_URL;
        document.head.appendChild(script);
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', loadWidget);
      } else {
        loadWidget();
      }
    })();
  </script>

{% else %}
  {% if request.design_mode %}
    <div class="quizsnap-placeholder" style="border: 2px dashed #ccc; padding: 2rem; text-align: center; color: #888; border-radius: 8px;">
      <p style="margin: 0; font-size: 0.875rem;">QuizSnap: Select a quiz slug in the block settings to display your quiz here.</p>
    </div>
  {% endif %}
{% endif %}

{% schema %}
{
  "name": "QuizSnap Quiz",
  "target": "section",
  "settings": [
    {
      "type": "text",
      "id": "quiz_slug",
      "label": "Quiz Slug",
      "info": "Find the quiz slug in your QuizSnap app under Quizzes > Share."
    },
    {
      "type": "select",
      "id": "display_mode",
      "label": "Display Mode",
      "options": [
        { "value": "embedded", "label": "Embedded (inline)" },
        { "value": "popup", "label": "Popup (centered overlay)" },
        { "value": "slide-in", "label": "Slide-in (side panel)" }
      ],
      "default": "embedded"
    },
    {
      "type": "text",
      "id": "button_text",
      "label": "Button Text",
      "default": "Take the quiz",
      "info": "Text shown on the trigger button (popup and slide-in modes only)."
    },
    {
      "type": "color",
      "id": "button_color",
      "label": "Button / Primary Color",
      "default": "#5C6AC4"
    },
    {
      "type": "select",
      "id": "width",
      "label": "Width",
      "options": [
        { "value": "full", "label": "Full width" },
        { "value": "medium", "label": "Medium (720px)" },
        { "value": "narrow", "label": "Narrow (480px)" }
      ],
      "default": "full"
    }
  ],
  "presets": [
    {
      "name": "QuizSnap Quiz"
    }
  ]
}
{% endschema %}

/*!
 * QuizSnap Widget Runtime v1.0.0
 * Vanilla JS — no dependencies — <20KB gzipped target
 */
(function () {
  "use strict";

  // ── Constants ────────────────────────────────────────────────────────────────
  var APP_URL = (document.currentScript && document.currentScript.dataset.appUrl) || "";
  var CACHE_TTL = 300000; // 5 minutes

  var State = { LOADING: "loading", ACTIVE: "active", COMPLETE: "complete", ERROR: "error" };

  var QuestionType = {
    MULTIPLE_CHOICE: "multiple-choice",
    IMAGE_CHOICE: "image-choice",
    SLIDER: "slider",
    TEXT_INPUT: "text-input",
    EMAIL: "email",
    DATE: "date",
    DROPDOWN: "dropdown",
    RATING: "rating",
  };

  // ── Utilities ─────────────────────────────────────────────────────────────────
  function safeJson(str, fallback) {
    try { return JSON.parse(str); } catch (_) { return fallback; }
  }

  function getSessionId() {
    var key = "qs_sid";
    var id = sessionStorage.getItem(key);
    if (!id) {
      id = "xxxx-xxxx-xxxx".replace(/x/g, function () {
        return Math.random().toString(36)[2];
      }) + "-" + Date.now().toString(36);
      sessionStorage.setItem(key, id);
    }
    return id;
  }

  function getDeviceType() {
    return window.innerWidth < 768 ? "mobile" : window.innerWidth < 1024 ? "tablet" : "desktop";
  }

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (k === "className") { node.className = attrs[k]; }
        else if (k === "textContent") { node.textContent = attrs[k]; }
        else if (k === "innerHTML") { node.innerHTML = attrs[k]; }
        else if (k.startsWith("data-")) { node.setAttribute(k, attrs[k]); }
        else if (k.startsWith("aria-")) { node.setAttribute(k, attrs[k]); }
        else { node[k] = attrs[k]; }
      });
    }
    if (children) {
      children.forEach(function (c) { if (c) node.appendChild(c); });
    }
    return node;
  }

  function txt(content) { return document.createTextNode(content); }

  function esc(str) {
    var d = document.createElement("div");
    d.textContent = String(str || "");
    return d.innerHTML;
  }

  // ── Cache helpers ─────────────────────────────────────────────────────────────
  function cacheGet(key) {
    try {
      var raw = sessionStorage.getItem(key);
      if (!raw) return null;
      var entry = JSON.parse(raw);
      if (Date.now() - entry.ts > CACHE_TTL) { sessionStorage.removeItem(key); return null; }
      return entry.data;
    } catch (_) { return null; }
  }

  function cacheSet(key, data) {
    try { sessionStorage.setItem(key, JSON.stringify({ data: data, ts: Date.now() })); } catch (_) {}
  }

  // ── API helpers ───────────────────────────────────────────────────────────────
  function fetchQuiz(slug, shop) {
    var cacheKey = "qs_quiz_" + slug + "_" + shop;
    var cached = cacheGet(cacheKey);
    if (cached) return Promise.resolve(cached);
    return fetch(APP_URL + "/api/quiz/" + encodeURIComponent(slug) + "?shop=" + encodeURIComponent(shop))
      .then(function (r) {
        if (!r.ok) throw new Error("Quiz not found (" + r.status + ")");
        return r.json();
      })
      .then(function (data) {
        cacheSet(cacheKey, data);
        return data;
      });
  }

  function submitQuiz(slug, shop, payload) {
    return fetch(
      APP_URL + "/api/quiz/" + encodeURIComponent(slug) + "/submit?shop=" + encodeURIComponent(shop),
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      }
    ).then(function (r) { return r.json(); });
  }

  function trackEvent(shop, quizId, eventType, sessionId, data) {
    fetch(APP_URL + "/api/analytics", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ shop: shop, quizId: quizId, eventType: eventType, sessionId: sessionId, data: data || {} }),
    }).catch(function () {});
  }

  // ── Logic Engine ──────────────────────────────────────────────────────────────
  function evaluateLogic(question, selectedAnswerIds) {
    var logic = safeJson(question.logic, {});
    var rules = Array.isArray(logic.rules) ? logic.rules : [];
    for (var i = 0; i < rules.length; i++) {
      var rule = rules[i];
      if (rule.if && rule.if.answerId && selectedAnswerIds.indexOf(rule.if.answerId) !== -1) {
        return rule.goto || null;
      }
    }
    return null;
  }

  // ── Widget Class ──────────────────────────────────────────────────────────────
  function QuizSnapWidget(container) {
    this.container = container;
    this.slug = container.dataset.quizsnapQuiz || container.dataset["quizsnap-quiz"];
    this.shop = container.dataset.shop || (window.Shopify && window.Shopify.shop) || "";
    this.displayMode = container.dataset.displayMode || "embedded";
    this.sessionId = getSessionId();
    this.state = State.LOADING;
    this.quiz = null;
    this.questions = [];
    this.currentIndex = 0;
    this.responses = {};    // questionId -> { answerId(s), value }
    this.email = null;

    this._init();
  }

  QuizSnapWidget.prototype._init = function () {
    var self = this;
    if (!self.slug || !self.shop) {
      self._setState(State.ERROR, "Missing quiz slug or shop.");
      return;
    }
    fetchQuiz(self.slug, self.shop)
      .then(function (quiz) {
        self.quiz = quiz;
        self.questions = (quiz.questions || []).filter(function (q) { return q.required !== false; });
        self._setState(State.ACTIVE);
        trackEvent(self.shop, quiz.id, "quiz_started", self.sessionId, { source: document.referrer ? "referral" : "direct", deviceType: getDeviceType() });
      })
      .catch(function (err) {
        self._setState(State.ERROR, err.message || "Failed to load quiz.");
      });
  };

  QuizSnapWidget.prototype._setState = function (state, message) {
    this.state = state;
    this._render(message);
  };

  QuizSnapWidget.prototype._render = function (message) {
    var self = this;
    self.container.innerHTML = "";

    if (self.state === State.LOADING) {
      var spinner = el("div", { className: "quizsnap-loading", role: "status", "aria-live": "polite" }, [
        el("div", { className: "quizsnap-spinner", "aria-hidden": "true" }),
        el("span", { className: "quizsnap-loading__text", textContent: "Loading quiz\u2026" }),
      ]);
      self.container.appendChild(spinner);
      return;
    }

    if (self.state === State.ERROR) {
      var errDiv = el("div", { className: "quizsnap-error", role: "alert" }, [
        el("p", { textContent: message || "Something went wrong. Please try again." }),
      ]);
      self.container.appendChild(errDiv);
      return;
    }

    if (self.state === State.ACTIVE) {
      self._renderQuestion();
      return;
    }

    if (self.state === State.COMPLETE) {
      self._renderResults(message);
      return;
    }
  };

  // ── Question Rendering ────────────────────────────────────────────────────────
  QuizSnapWidget.prototype._renderQuestion = function () {
    var self = this;
    var q = self.questions[self.currentIndex];
    if (!q) return;

    var settings = safeJson(q.settings, {});
    var total = self.questions.length;
    var pct = Math.round(((self.currentIndex) / total) * 100);

    var wrap = el("div", { className: "quizsnap-quiz" });

    // Progress bar
    var quiz = self.quiz;
    var quizSettings = safeJson(quiz.settings, {});
    if (quizSettings.showProgressBar !== false) {
      var progressWrap = el("div", { className: "quizsnap-progress", role: "progressbar", "aria-valuenow": pct, "aria-valuemin": "0", "aria-valuemax": "100", "aria-label": "Quiz progress" });
      var progressBar = el("div", { className: "quizsnap-progress__bar" });
      progressBar.style.width = pct + "%";
      progressWrap.appendChild(progressBar);

      var progressLabel = el("span", { className: "quizsnap-progress__label", "aria-hidden": "true", textContent: "Question " + (self.currentIndex + 1) + " of " + total });
      wrap.appendChild(progressWrap);
      wrap.appendChild(progressLabel);
    }

    // Question header
    var header = el("div", { className: "quizsnap-question" });
    var titleEl = el("h2", { className: "quizsnap-question__title", textContent: q.title });
    header.appendChild(titleEl);
    if (q.description) {
      header.appendChild(el("p", { className: "quizsnap-question__desc", textContent: q.description }));
    }
    if (q.imageUrl) {
      var img = el("img", { className: "quizsnap-question__img", src: q.imageUrl, alt: q.title });
      header.appendChild(img);
    }
    wrap.appendChild(header);

    // Input area
    var inputWrap = el("div", { className: "quizsnap-input" });
    self._renderInput(q, settings, inputWrap);
    wrap.appendChild(inputWrap);

    // Navigation
    var nav = self._buildNav(q);
    wrap.appendChild(nav);

    self.container.appendChild(wrap);

    // Restore selection state if user went back
    self._restoreSelection(q);

    // Focus first focusable element
    var firstFocusable = wrap.querySelector("button, input, select, [tabindex]");
    if (firstFocusable) { setTimeout(function () { firstFocusable.focus(); }, 50); }
  };

  QuizSnapWidget.prototype._renderInput = function (q, settings, container) {
    var self = this;
    var type = q.type;
    var answers = q.answers || [];

    if (type === QuestionType.MULTIPLE_CHOICE) {
      var isMulti = settings.allowMultiple || false;
      var list = el("ul", { className: "quizsnap-options", role: "list" });
      answers.forEach(function (ans) {
        var li = el("li", { className: "quizsnap-options__item" });
        var btn = el("button", {
          className: "quizsnap-option",
          type: "button",
          textContent: ans.text,
          "data-answer-id": ans.id,
          role: isMulti ? "checkbox" : "radio",
          "aria-checked": "false",
        });
        btn.addEventListener("click", function () {
          self._selectOption(q, ans.id, isMulti, list);
        });
        li.appendChild(btn);
        list.appendChild(li);
      });
      container.appendChild(list);

    } else if (type === QuestionType.IMAGE_CHOICE) {
      var grid = el("div", { className: "quizsnap-image-grid", role: "list" });
      answers.forEach(function (ans) {
        var item = el("div", { className: "quizsnap-image-grid__item", role: "listitem" });
        var btn = el("button", {
          className: "quizsnap-option quizsnap-option--image",
          type: "button",
          "data-answer-id": ans.id,
          "aria-pressed": "false",
          "aria-label": ans.text,
        });
        if (ans.imageUrl) {
          var img = el("img", { src: ans.imageUrl, alt: ans.text, className: "quizsnap-option__img" });
          btn.appendChild(img);
        }
        btn.appendChild(el("span", { className: "quizsnap-option__label", textContent: ans.text }));
        btn.addEventListener("click", function () {
          self._selectOption(q, ans.id, false, grid);
        });
        item.appendChild(btn);
        grid.appendChild(item);
      });
      container.appendChild(grid);

    } else if (type === QuestionType.SLIDER) {
      var min = settings.min != null ? settings.min : 0;
      var max = settings.max != null ? settings.max : 100;
      var step = settings.step || 1;
      var unit = settings.unit || "";
      var sliderId = "qs-slider-" + q.id;
      var sliderWrap = el("div", { className: "quizsnap-slider" });
      var labelsRow = el("div", { className: "quizsnap-slider__labels", "aria-hidden": "true" });
      labelsRow.appendChild(el("span", { textContent: settings.minLabel || String(min) + (unit ? " " + unit : "") }));
      labelsRow.appendChild(el("span", { textContent: settings.maxLabel || String(max) + (unit ? " " + unit : "") }));
      sliderWrap.appendChild(labelsRow);
      var sliderInput = el("input", {
        type: "range",
        id: sliderId,
        className: "quizsnap-slider__input",
        min: String(min),
        max: String(max),
        step: String(step),
        value: String(Math.round((min + max) / 2)),
        "aria-label": q.title,
        "aria-valuemin": String(min),
        "aria-valuemax": String(max),
      });
      var valueDisplay = el("output", { className: "quizsnap-slider__value", htmlFor: sliderId });
      valueDisplay.textContent = sliderInput.value + (unit ? " " + unit : "");
      sliderInput.addEventListener("input", function () {
        valueDisplay.textContent = sliderInput.value + (unit ? " " + unit : "");
        self.responses[q.id] = { value: sliderInput.value };
      });
      // Set initial value
      self.responses[q.id] = { value: sliderInput.value };
      sliderWrap.appendChild(sliderInput);
      sliderWrap.appendChild(valueDisplay);
      container.appendChild(sliderWrap);

    } else if (type === QuestionType.TEXT_INPUT) {
      var inputId = "qs-text-" + q.id;
      var label = el("label", { htmlFor: inputId, className: "quizsnap-label quizsnap-sr-only", textContent: q.title });
      var textInput = el("input", {
        type: "text",
        id: inputId,
        className: "quizsnap-text-input",
        placeholder: settings.placeholder || "Type your answer\u2026",
        maxLength: settings.maxLength || 500,
        "aria-label": q.title,
        "aria-required": q.required ? "true" : "false",
      });
      textInput.addEventListener("input", function () {
        self.responses[q.id] = { value: textInput.value };
      });
      container.appendChild(label);
      container.appendChild(textInput);

    } else if (type === QuestionType.EMAIL) {
      var emailId = "qs-email-" + q.id;
      var consentId = "qs-consent-" + q.id;
      var emailWrap = el("div", { className: "quizsnap-email" });
      var emailLabel = el("label", { htmlFor: emailId, className: "quizsnap-label", textContent: "Email address" });
      var emailInput = el("input", {
        type: "email",
        id: emailId,
        className: "quizsnap-text-input",
        placeholder: "you@example.com",
        autocomplete: "email",
        "aria-label": "Email address",
        "aria-required": q.required ? "true" : "false",
      });
      emailInput.addEventListener("input", function () {
        self.email = emailInput.value;
        self.responses[q.id] = { value: emailInput.value };
      });
      emailWrap.appendChild(emailLabel);
      emailWrap.appendChild(emailInput);

      if (settings.consentText) {
        var consentWrap = el("div", { className: "quizsnap-consent" });
        var consentCheckbox = el("input", {
          type: "checkbox",
          id: consentId,
          className: "quizsnap-consent__checkbox",
          "aria-label": settings.consentText,
        });
        var consentLabel = el("label", { htmlFor: consentId, className: "quizsnap-consent__label", textContent: settings.consentText });
        consentWrap.appendChild(consentCheckbox);
        consentWrap.appendChild(consentLabel);
        emailWrap.appendChild(consentWrap);
      }
      container.appendChild(emailWrap);

    } else if (type === QuestionType.DROPDOWN) {
      var selectId = "qs-select-" + q.id;
      var selectLabel = el("label", { htmlFor: selectId, className: "quizsnap-label quizsnap-sr-only", textContent: q.title });
      var select = el("select", {
        id: selectId,
        className: "quizsnap-select",
        "aria-label": q.title,
        "aria-required": q.required ? "true" : "false",
      });
      select.appendChild(el("option", { value: "", textContent: "Select an option\u2026" }));
      answers.forEach(function (ans) {
        var opt = el("option", { value: ans.id, textContent: ans.text });
        select.appendChild(opt);
      });
      select.addEventListener("change", function () {
        self.responses[q.id] = { answerId: select.value };
      });
      container.appendChild(selectLabel);
      container.appendChild(select);

    } else if (type === QuestionType.RATING) {
      var maxRating = settings.maxRating || 5;
      var ratingWrap = el("div", { className: "quizsnap-rating", role: "group", "aria-label": q.title });
      for (var r = 1; r <= maxRating; r++) {
        (function (val) {
          var starBtn = el("button", {
            type: "button",
            className: "quizsnap-rating__star",
            "aria-label": val + " out of " + maxRating,
            "aria-pressed": "false",
            "data-value": String(val),
          });
          starBtn.innerHTML = "<svg viewBox='0 0 24 24' width='28' height='28' aria-hidden='true' focusable='false'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z' fill='currentColor'/></svg>";
          starBtn.addEventListener("click", function () {
            self.responses[q.id] = { value: String(val) };
            ratingWrap.querySelectorAll(".quizsnap-rating__star").forEach(function (s, idx) {
              var active = (idx + 1) <= val;
              s.classList.toggle("quizsnap-rating__star--active", active);
              s.setAttribute("aria-pressed", active ? "true" : "false");
            });
          });
          ratingWrap.appendChild(starBtn);
        }(r));
      }
      container.appendChild(ratingWrap);

    } else if (type === QuestionType.DATE) {
      var dateId = "qs-date-" + q.id;
      var dateLabelEl = el("label", { htmlFor: dateId, className: "quizsnap-label quizsnap-sr-only", textContent: q.title });
      var dateInput = el("input", {
        type: "date",
        id: dateId,
        className: "quizsnap-text-input",
        "aria-label": q.title,
        "aria-required": q.required ? "true" : "false",
      });
      dateInput.addEventListener("change", function () {
        self.responses[q.id] = { value: dateInput.value };
      });
      container.appendChild(dateLabelEl);
      container.appendChild(dateInput);
    }
  };

  QuizSnapWidget.prototype._selectOption = function (q, answerId, isMulti, container) {
    var self = this;
    var btns = container.querySelectorAll("[data-answer-id]");

    if (isMulti) {
      var existing = (self.responses[q.id] && self.responses[q.id].answerIds) ? self.responses[q.id].answerIds : [];
      var idx = existing.indexOf(answerId);
      if (idx === -1) { existing = existing.concat([answerId]); }
      else { existing = existing.filter(function (id) { return id !== answerId; }); }
      self.responses[q.id] = { answerIds: existing };
      btns.forEach(function (btn) {
        var selected = existing.indexOf(btn.dataset.answerId) !== -1;
        btn.classList.toggle("quizsnap-option--selected", selected);
        btn.setAttribute("aria-checked", selected ? "true" : "false");
        if (btn.hasAttribute("aria-pressed")) btn.setAttribute("aria-pressed", selected ? "true" : "false");
      });
    } else {
      self.responses[q.id] = { answerId: answerId };
      btns.forEach(function (btn) {
        var selected = btn.dataset.answerId === answerId;
        btn.classList.toggle("quizsnap-option--selected", selected);
        btn.setAttribute("aria-checked", selected ? "true" : "false");
        if (btn.hasAttribute("aria-pressed")) btn.setAttribute("aria-pressed", selected ? "true" : "false");
      });
    }
  };

  QuizSnapWidget.prototype._restoreSelection = function (q) {
    var self = this;
    var resp = self.responses[q.id];
    if (!resp) return;

    if (resp.answerId) {
      var btn = self.container.querySelector('[data-answer-id="' + resp.answerId + '"]');
      if (btn) {
        btn.classList.add("quizsnap-option--selected");
        btn.setAttribute("aria-checked", "true");
        if (btn.hasAttribute("aria-pressed")) btn.setAttribute("aria-pressed", "true");
      }
    }
    if (resp.answerIds) {
      resp.answerIds.forEach(function (id) {
        var b = self.container.querySelector('[data-answer-id="' + id + '"]');
        if (b) {
          b.classList.add("quizsnap-option--selected");
          b.setAttribute("aria-checked", "true");
          if (b.hasAttribute("aria-pressed")) b.setAttribute("aria-pressed", "true");
        }
      });
    }
    if (resp.value != null) {
      var textInput = self.container.querySelector("input[type=text], input[type=email], input[type=date], input[type=range]");
      if (textInput) textInput.value = resp.value;
      var slider = self.container.querySelector(".quizsnap-slider__input");
      var output = self.container.querySelector(".quizsnap-slider__value");
      if (slider && output) { slider.value = resp.value; output.textContent = resp.value; }
    }
  };

  QuizSnapWidget.prototype._buildNav = function (q) {
    var self = this;
    var nav = el("div", { className: "quizsnap-nav" });

    if (self.currentIndex > 0) {
      var backBtn = el("button", { type: "button", className: "quizsnap-btn quizsnap-btn--secondary", textContent: "Back" });
      backBtn.addEventListener("click", function () {
        self.currentIndex--;
        self._render();
      });
      nav.appendChild(backBtn);
    } else {
      nav.appendChild(el("span", {})); // spacer
    }

    var isLast = self.currentIndex === self.questions.length - 1;
    var nextBtn = el("button", {
      type: "button",
      className: "quizsnap-btn quizsnap-btn--primary",
      textContent: isLast ? "See my results" : "Next",
    });
    nextBtn.addEventListener("click", function () {
      self._handleNext(q);
    });
    nav.appendChild(nextBtn);

    return nav;
  };

  QuizSnapWidget.prototype._handleNext = function (q) {
    var self = this;
    var resp = self.responses[q.id];

    // Validate required fields
    if (q.required) {
      if (!resp) {
        self._showValidationError(q, "Please answer this question before continuing.");
        return;
      }
      if (q.type === QuestionType.EMAIL) {
        var emailVal = resp.value || "";
        if (!emailVal || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailVal)) {
          self._showValidationError(q, "Please enter a valid email address.");
          return;
        }
      }
    }

    // Evaluate skip logic
    var selectedIds = [];
    if (resp) {
      if (resp.answerId) selectedIds = [resp.answerId];
      if (resp.answerIds) selectedIds = resp.answerIds;
    }
    var goto = evaluateLogic(q, selectedIds);

    if (goto === "results") {
      self._submitQuiz();
      return;
    }

    if (goto) {
      var gotoIdx = self.questions.findIndex(function (qi) { return qi.id === goto; });
      if (gotoIdx !== -1) {
        self.currentIndex = gotoIdx;
        self._render();
        return;
      }
    }

    // Check per-answer nextQuestionId
    var firstSelectedId = selectedIds[0];
    if (firstSelectedId) {
      var answer = (q.answers || []).find(function (a) { return a.id === firstSelectedId; });
      if (answer && answer.nextQuestionId) {
        var nextIdx = self.questions.findIndex(function (qi) { return qi.id === answer.nextQuestionId; });
        if (nextIdx !== -1) {
          self.currentIndex = nextIdx;
          self._render();
          return;
        }
      }
    }

    // Standard linear advance
    if (self.currentIndex < self.questions.length - 1) {
      self.currentIndex++;
      self._render();
    } else {
      self._submitQuiz();
    }
  };

  QuizSnapWidget.prototype._showValidationError = function (q, message) {
    var existing = this.container.querySelector(".quizsnap-validation");
    if (existing) existing.remove();
    var errEl = el("p", {
      className: "quizsnap-validation",
      role: "alert",
      "aria-live": "assertive",
      textContent: message,
    });
    var input = this.container.querySelector(".quizsnap-input");
    if (input) input.appendChild(errEl);
  };

  QuizSnapWidget.prototype._submitQuiz = function () {
    var self = this;
    self._setState(State.LOADING);

    var answers = Object.keys(self.responses).map(function (qId) {
      var r = self.responses[qId];
      return { questionId: qId, answerId: r.answerId || null, answerIds: r.answerIds || null, value: r.value != null ? String(r.value) : null };
    });

    var payload = {
      sessionId: self.sessionId,
      answers: answers,
      email: self.email || null,
      source: self.displayMode === "popup" || self.displayMode === "slide-in" ? self.displayMode : "embed",
      deviceType: getDeviceType(),
    };

    submitQuiz(self.slug, self.shop, payload)
      .then(function (result) {
        trackEvent(self.shop, self.quiz.id, "quiz_completed", self.sessionId, { totalQuestions: self.questions.length });
        self._setState(State.COMPLETE, result);
      })
      .catch(function () {
        self._setState(State.ERROR, "Failed to submit. Please try again.");
      });
  };

  // ── Results Rendering ─────────────────────────────────────────────────────────
  QuizSnapWidget.prototype._renderResults = function (result) {
    var self = this;
    result = result || {};

    var wrap = el("div", { className: "quizsnap-results" });

    var resultPage = result.resultPage || {};
    var products = result.recommendations || [];

    // Header
    var header = el("div", { className: "quizsnap-results__header" });
    header.appendChild(el("h2", { className: "quizsnap-results__title", textContent: resultPage.title || "Your Results" }));
    if (resultPage.description) {
      header.appendChild(el("p", { className: "quizsnap-results__desc", textContent: resultPage.description }));
    }
    wrap.appendChild(header);

    // Discount
    if (resultPage.showDiscount && resultPage.discountCode) {
      var disc = el("div", { className: "quizsnap-discount" });
      disc.appendChild(el("p", { className: "quizsnap-discount__label", textContent: "Your exclusive discount:" }));
      disc.appendChild(el("code", { className: "quizsnap-discount__code", textContent: resultPage.discountCode }));
      if (resultPage.discountValue) {
        var discType = resultPage.discountType === "percentage" ? "%" : " off";
        disc.appendChild(el("span", { className: "quizsnap-discount__value", textContent: resultPage.discountValue + discType }));
      }
      wrap.appendChild(disc);
    }

    // Products grid
    if (products.length > 0) {
      var layout = resultPage.layout || "grid";
      var grid = el("div", { className: "quizsnap-product-grid quizsnap-product-grid--" + layout });
      products.forEach(function (product) {
        grid.appendChild(self._buildProductCard(product, resultPage));
      });
      wrap.appendChild(grid);
    } else {
      var noProds = el("p", { className: "quizsnap-results__empty", textContent: "No specific recommendations at this time. Browse our full collection below." });
      wrap.appendChild(noProds);
    }

    // CTA
    if (resultPage.ctaText && resultPage.ctaUrl) {
      var ctaWrap = el("div", { className: "quizsnap-results__cta" });
      var ctaLink = el("a", {
        href: resultPage.ctaUrl,
        className: "quizsnap-btn quizsnap-btn--primary",
        textContent: resultPage.ctaText,
      });
      ctaWrap.appendChild(ctaLink);
      wrap.appendChild(ctaWrap);
    }

    // Retake
    var retakeWrap = el("div", { className: "quizsnap-results__retake" });
    var retakeBtn = el("button", { type: "button", className: "quizsnap-btn quizsnap-btn--ghost", textContent: "Retake quiz" });
    retakeBtn.addEventListener("click", function () {
      self.currentIndex = 0;
      self.responses = {};
      self.email = null;
      self._setState(State.ACTIVE);
    });
    retakeWrap.appendChild(retakeBtn);
    wrap.appendChild(retakeWrap);

    self.container.appendChild(wrap);
  };

  QuizSnapWidget.prototype._buildProductCard = function (product, resultPage) {
    var self = this;
    var card = el("div", { className: "quizsnap-product" });

    if (product.imageUrl || product.image) {
      var imgUrl = product.imageUrl || product.image;
      var imgWrap = el("div", { className: "quizsnap-product__img-wrap" });
      imgWrap.appendChild(el("img", { src: imgUrl, alt: product.title, className: "quizsnap-product__img", loading: "lazy" }));
      card.appendChild(imgWrap);
    }

    var info = el("div", { className: "quizsnap-product__info" });
    info.appendChild(el("h3", { className: "quizsnap-product__title", textContent: product.title }));

    if (product.price || product.priceMin) {
      var price = product.price || product.priceMin;
      info.appendChild(el("p", { className: "quizsnap-product__price", textContent: "$" + parseFloat(price).toFixed(2) }));
    }

    var actions = el("div", { className: "quizsnap-product__actions" });

    // View product
    var productUrl = product.url || ("https://" + self.shop + "/products/" + product.handle);
    var viewBtn = el("a", {
      href: productUrl,
      className: "quizsnap-btn quizsnap-btn--secondary quizsnap-btn--sm",
      textContent: "View product",
    });
    viewBtn.addEventListener("click", function () {
      trackEvent(self.shop, self.quiz.id, "product_clicked", self.sessionId, { productId: product.id || product.productGid });
    });
    actions.appendChild(viewBtn);

    info.appendChild(actions);
    card.appendChild(info);
    return card;
  };

  // ── Popup / Slide-in handling ─────────────────────────────────────────────────
  function initTriggerButtons() {
    document.querySelectorAll(".quizsnap-trigger-wrap").forEach(function (triggerWrap) {
      var slug = triggerWrap.dataset.quizsnapQuiz || triggerWrap.dataset["quizsnap-quiz"];
      var modalId = "quizsnap-modal-" + triggerWrap.dataset.blockId;
      var modal = document.getElementById(modalId);
      if (!modal) return;

      var triggerBtn = triggerWrap.querySelector(".quizsnap-trigger-btn");
      if (!triggerBtn) return;

      var widgetContainer = modal.querySelector(".quizsnap");
      var widgetInstance = null;

      triggerBtn.addEventListener("click", function () {
        modal.removeAttribute("hidden");
        modal.setAttribute("aria-hidden", "false");
        modal.classList.add("quizsnap-overlay--open");
        document.body.style.overflow = "hidden";

        if (!widgetInstance && widgetContainer) {
          widgetInstance = new QuizSnapWidget(widgetContainer);
        }

        // Focus the close button
        var closeBtn = modal.querySelector(".quizsnap-overlay__close");
        if (closeBtn) { setTimeout(function () { closeBtn.focus(); }, 100); }
      });

      // Close handlers
      modal.querySelectorAll("[data-quizsnap-close]").forEach(function (closer) {
        closer.addEventListener("click", function () {
          closeModal(modal);
          triggerBtn.focus();
        });
      });

      // Escape key
      modal.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
          closeModal(modal);
          triggerBtn.focus();
        }
        // Trap focus inside modal
        if (e.key === "Tab") {
          var focusable = modal.querySelectorAll('button, input, select, a[href], [tabindex]:not([tabindex="-1"])');
          var arr = Array.prototype.slice.call(focusable);
          if (!arr.length) return;
          var first = arr[0];
          var last = arr[arr.length - 1];
          if (e.shiftKey && document.activeElement === first) {
            e.preventDefault(); last.focus();
          } else if (!e.shiftKey && document.activeElement === last) {
            e.preventDefault(); first.focus();
          }
        }
      });
    });
  }

  function closeModal(modal) {
    modal.setAttribute("hidden", "");
    modal.setAttribute("aria-hidden", "true");
    modal.classList.remove("quizsnap-overlay--open");
    document.body.style.overflow = "";
  }

  // ── Boot ──────────────────────────────────────────────────────────────────────
  function boot() {
    // Initialize all embedded quizzes
    document.querySelectorAll(".quizsnap[data-quizsnap-quiz]").forEach(function (container) {
      if (!container.dataset.quizsnapInit) {
        container.dataset.quizsnapInit = "1";
        new QuizSnapWidget(container);
      }
    });

    // Initialize popup/slide-in triggers
    initTriggerButtons();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

/* QuizSnap Widget Styles — <5KB gzipped target */
/* Uses CSS custom properties for merchant theming */

/* ── Custom Properties (Theme Tokens) ──────────────────────────────────────── */
.quizsnap {
  --qs-primary: #5C6AC4;
  --qs-primary-hover: #4959bd;
  --qs-primary-text: #ffffff;
  --qs-text: #1a1a1a;
  --qs-text-muted: #6b7280;
  --qs-bg: #ffffff;
  --qs-border: #e5e7eb;
  --qs-border-hover: #d1d5db;
  --qs-selected-bg: color-mix(in srgb, var(--qs-primary) 10%, transparent);
  --qs-radius: 8px;
  --qs-radius-sm: 4px;
  --qs-shadow: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --qs-shadow-md: 0 4px 12px rgba(0,0,0,.12);
  --qs-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --qs-transition: 160ms ease;
  --qs-spacing: 1.25rem;
}

/* ── Base Container ─────────────────────────────────────────────────────────── */
.quizsnap {
  box-sizing: border-box;
  font-family: var(--qs-font);
  color: var(--qs-text);
  background: var(--qs-bg);
  border-radius: var(--qs-radius);
  padding: var(--qs-spacing);
  max-width: 100%;
}

.quizsnap *,
.quizsnap *::before,
.quizsnap *::after {
  box-sizing: inherit;
}

/* ── Width Variants (set on .quizsnap-block wrapper) ──────────────────────── */
.quizsnap-width--full { width: 100%; }
.quizsnap-width--medium { max-width: 720px; margin-inline: auto; }
.quizsnap-width--narrow { max-width: 480px; margin-inline: auto; }

/* ── Progress Bar ───────────────────────────────────────────────────────────── */
.quizsnap-progress {
  height: 6px;
  background: var(--qs-border);
  border-radius: 3px;
  margin-bottom: .5rem;
  overflow: hidden;
}

.quizsnap-progress__bar {
  height: 100%;
  background: var(--qs-primary);
