}

.quizsnap-btn--secondary {
  background: var(--qs-bg);
  color: var(--qs-text);
  border-color: var(--qs-border);
}

.quizsnap-btn--secondary:hover { border-color: var(--qs-border-hover); background: #f9fafb; }

.quizsnap-btn--ghost {
  background: none;
  color: var(--qs-text-muted);
  border-color: transparent;
  padding-inline: .75rem;
  font-size: .875rem;
}

.quizsnap-btn--ghost:hover { color: var(--qs-text); text-decoration: underline; }

.quizsnap-btn--sm { padding: .5rem 1rem; font-size: .875rem; }

/* ── Validation Error ────────────────────────────────────────────────────────── */
.quizsnap-validation {
  margin-top: .5rem;
  font-size: .875rem;
  color: #dc2626;
  font-weight: 500;
}

/* ── Loading Spinner ─────────────────────────────────────────────────────────── */
.quizsnap-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2.5rem;
  gap: 1rem;
}

.quizsnap-spinner {
  width: 36px;
  height: 36px;
  border: 3px solid var(--qs-border);
  border-top-color: var(--qs-primary);
  border-radius: 50%;
  animation: qs-spin .7s linear infinite;
}

@keyframes qs-spin { to { transform: rotate(360deg); } }

.quizsnap-loading__text {
  font-size: .875rem;
  color: var(--qs-text-muted);
}

/* ── Error State ─────────────────────────────────────────────────────────────── */
.quizsnap-error {
  padding: 1.5rem;
  text-align: center;
  color: #dc2626;
  font-size: .9375rem;
  border: 1px solid #fecaca;
  border-radius: var(--qs-radius);
  background: #fef2f2;
}

/* ── Results Page ────────────────────────────────────────────────────────────── */
.quizsnap-results {}

.quizsnap-results__header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.quizsnap-results__title {
  font-size: 1.375rem;
  font-weight: 700;
  margin: 0 0 .5rem;
  color: var(--qs-text);
}

.quizsnap-results__desc {
  font-size: .9375rem;
  color: var(--qs-text-muted);
  margin: 0;
  line-height: 1.55;
}

.quizsnap-results__cta { text-align: center; margin-top: 1.5rem; }
.quizsnap-results__retake { text-align: center; margin-top: 1rem; }
.quizsnap-results__empty { text-align: center; color: var(--qs-text-muted); font-size: .9375rem; }

/* ── Discount ────────────────────────────────────────────────────────────────── */
.quizsnap-discount {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: .625rem;
  justify-content: center;
  padding: 1rem 1.25rem;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: var(--qs-radius);
  margin-bottom: 1.5rem;
}

.quizsnap-discount__label { font-size: .875rem; color: #166534; margin: 0; }

.quizsnap-discount__code {
  font-size: 1rem;
  font-weight: 700;
  color: #166534;
  background: #dcfce7;
  padding: .25rem .625rem;
  border-radius: var(--qs-radius-sm);
  letter-spacing: .05em;
}

.quizsnap-discount__value {
  font-size: .875rem;
  color: #166534;
  font-weight: 500;
}

/* ── Product Grid ────────────────────────────────────────────────────────────── */
.quizsnap-product-grid {
  display: grid;
  gap: 1rem;
}

.quizsnap-product-grid--grid {
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
}

.quizsnap-product-grid--list {
  grid-template-columns: 1fr;
}

.quizsnap-product-grid--carousel {
  grid-auto-flow: column;
  grid-auto-columns: 200px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x mandatory;
  padding-bottom: .5rem;
}

/* ── Product Card ────────────────────────────────────────────────────────────── */
.quizsnap-product {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--qs-border);
  border-radius: var(--qs-radius);
  overflow: hidden;
  transition: box-shadow var(--qs-transition), transform var(--qs-transition);
  background: var(--qs-bg);
  scroll-snap-align: start;
}

.quizsnap-product:hover {
  box-shadow: var(--qs-shadow-md);
  transform: translateY(-2px);
}

.quizsnap-product__img-wrap {
  aspect-ratio: 1 / 1;
  overflow: hidden;
  background: #f9fafb;
}

.quizsnap-product__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .3s ease;
  display: block;
}

.quizsnap-product:hover .quizsnap-product__img { transform: scale(1.04); }

.quizsnap-product__info {
  padding: .875rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: .375rem;
}

.quizsnap-product__title {
  font-size: .9375rem;
  font-weight: 600;
  margin: 0;
  color: var(--qs-text);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.quizsnap-product__price {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--qs-text);
  margin: 0;
}

.quizsnap-product__actions { margin-top: auto; padding-top: .625rem; }

/* ── Trigger Button (popup/slide-in) ─────────────────────────────────────────── */
.quizsnap-trigger-wrap { display: inline-block; }

.quizsnap-trigger-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .8125rem 1.75rem;
  font-size: .9375rem;
  font-family: var(--qs-font);
  font-weight: 500;
  color: #ffffff;
  border: none;
  border-radius: var(--qs-radius);
  cursor: pointer;
  transition: opacity var(--qs-transition), transform var(--qs-transition);
  line-height: 1;
}

.quizsnap-trigger-btn:hover { opacity: .88; }
.quizsnap-trigger-btn:active { transform: scale(.98); }

.quizsnap-trigger-btn:focus-visible {
  outline: 2px solid var(--qs-primary);
  outline-offset: 3px;
}

/* ── Overlay (Popup + Slide-in) ──────────────────────────────────────────────── */
.quizsnap-overlay {
  position: fixed;
  inset: 0;
  z-index: 2147483640;
  display: flex;
  align-items: center;
  justify-content: center;
  visibility: hidden;
  opacity: 0;
  transition: opacity .2s ease, visibility .2s ease;
}

.quizsnap-overlay--open {
  visibility: visible;
  opacity: 1;
}

.quizsnap-overlay__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, .5);
  cursor: pointer;
}

.quizsnap-overlay__panel {
  position: relative;
  z-index: 1;
  background: var(--qs-bg, #fff);
  border-radius: var(--qs-radius);
  width: min(640px, calc(100vw - 2rem));
  max-height: min(90vh, 800px);
  overflow-y: auto;
  box-shadow: 0 20px 60px rgba(0,0,0,.25);
  transform: translateY(12px) scale(.97);
  transition: transform .2s ease;
}

.quizsnap-overlay--open .quizsnap-overlay__panel {
  transform: translateY(0) scale(1);
}

/* Slide-in variant */
.quizsnap-overlay--slide-in {
  justify-content: flex-end;
}

.quizsnap-overlay--slide-in .quizsnap-overlay__panel {
  border-radius: var(--qs-radius) 0 0 var(--qs-radius);
  height: 100%;
  max-height: 100vh;
  width: min(480px, 100vw);
  transform: translateX(100%);
}

.quizsnap-overlay--slide-in.quizsnap-overlay--open .quizsnap-overlay__panel {
  transform: translateX(0);
}

.quizsnap-overlay__close {
  position: sticky;
  top: .75rem;
  float: right;
  margin: .75rem .75rem 0 0;
  background: #f3f4f6;
  border: none;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--qs-text);
  transition: background var(--qs-transition);
  flex-shrink: 0;
  z-index: 2;
}

.quizsnap-overlay__close:hover { background: #e5e7eb; }

.quizsnap-overlay__close:focus-visible {
  outline: 2px solid var(--qs-primary);
  outline-offset: 2px;
}

/* Clear float from close button */
.quizsnap-overlay__panel > .quizsnap {
  clear: both;
}

/* ── Placeholder (Design Mode) ───────────────────────────────────────────────── */
.quizsnap-placeholder {
  padding: 2rem;
  text-align: center;
  border: 2px dashed #d1d5db;
  border-radius: var(--qs-radius);
  color: #9ca3af;
  font-size: .875rem;
  font-family: var(--qs-font);
}

/* ── Accessibility Utilities ─────────────────────────────────────────────────── */
.quizsnap-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Mobile Responsive ───────────────────────────────────────────────────────── */
@media (max-width: 767px) {
  .quizsnap {
    padding: 1rem;
    --qs-spacing: 1rem;
  }

  .quizsnap-question__title { font-size: 1.125rem; }

  .quizsnap-image-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .quizsnap-product-grid--grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .quizsnap-btn { padding: .6875rem 1.25rem; }

  .quizsnap-overlay__panel {
    width: 100vw;
    max-height: 95vh;
    margin-top: auto;
    align-self: flex-end;
    border-radius: var(--qs-radius) var(--qs-radius) 0 0;
    transform: translateY(100%);
  }

  .quizsnap-overlay--open .quizsnap-overlay__panel {
    transform: translateY(0);
  }

  .quizsnap-overlay--slide-in .quizsnap-overlay__panel {
    width: 100vw;
    border-radius: var(--qs-radius) var(--qs-radius) 0 0;
    transform: translateY(100%);
  }

  .quizsnap-overlay--slide-in.quizsnap-overlay--open .quizsnap-overlay__panel {
    transform: translateY(0);
  }
}

@media (max-width: 400px) {
  .quizsnap-image-grid { grid-template-columns: 1fr 1fr; }
  .quizsnap-product-grid--grid { grid-template-columns: 1fr; }
}

/* ── Reduced Motion ──────────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .quizsnap *,
  .quizsnap *::before,
  .quizsnap *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
}
